import httpStatus from 'http-status';
import { catchAsync } from 'utils/catchAsync';
import { friendRequestService } from 'services';

export const fetchAllFriends = catchAsync(async (req, res) => {
  const friends = await friendRequestService.getFriends(req.user._id, req.query);
  res.status(httpStatus.OK).send({ results: friends });
});

export const sendFriendRequest = catchAsync(async (req, res) => {
  const receiverId = req.body.receiverId || req.body.receiver;
  const friendRequest = await friendRequestService.sendFriendRequest(req.user._id, receiverId);
  res.status(httpStatus.CREATED).send({
    results: {
      message: 'Friend request sent successfully',
      friendRequest,
    },
  });
});

export const friendRequest = catchAsync(async (req, res) => {
  const result = await friendRequestService.respondToFriendRequest(req.params.id, req.user._id, req.body.status);
  res.status(httpStatus.OK).send({
    results: {
      message: `Friend request ${result.status} successfully`,
      friendRequest: result,
    },
  });
});

export const getFriendRequestWithPagination = catchAsync(async (req, res) => {
  const result = await friendRequestService.getFriendRequestsWithPagination(
    req.user._id,
    { status: req.query.status },
    req.query
  );
  res.status(httpStatus.OK).send({ results: result });
});

